/// <summary>
/// MPJ_3863 - kscerri - 05/08/2021
/// Tmp table
/// </summary>
/// <returns>tmp table</returns>
[SRSReportDataSetAttribute(tablestr(METVendAuditReportTmp))]
public METVendAuditReportTmp getVendAuditReportTmp()
{
    select vendAuditReportTmp;
    return vendAuditReportTmp;
}

    /// <summary>
    /// MPJ_3863 - kscerri - 05/08/2021
    /// Process report data.
    /// </summary>
    public void processReport()
    {
        Query query;

        contract = this.parmDataContract() as METVendAuditReportContract;

        query = this.processQuery();
        
        this.processdata(query);
    }

    /// <summary>
    /// MPJ_3863 - kscerri - 06/08/2021
    /// </summary>
    /// <returns>query</returns>
    public Query processQuery()
    {
        Query                   query;
        QueryBuildDataSource    qbdsVendTable, qbdsSysDataBaseLog, qbdsDirParty, qbdsVendBankAccount, qbdsVendTableBank;
        List                    vendGroupList   = new List(Types::String);
        List                    vendAccountList = new List(Types::String);
        List                    legalEntityList = new List(Types::String);
        ListEnumerator          vendGroupListEnum, vendAccountListEnum, legalEntityListEnum;

        query = new Query();

        qbdsSysDataBaseLog  = query.addDataSource(tableNum(SysDataBaseLog));

        qbdsVendTable       = qbdsSysDataBaseLog.addDataSource(tableNum(VendTable));
        qbdsVendTable.relations(false);
        qbdsVendTable.addLink(fieldNum(SysDataBaseLog, LogRecId), fieldNum(VendTable, RecId));
        qbdsVendTable.addSelectionField(fieldNum(VendTable, AccountNum));
        qbdsVendTable.fields().dynamic(0);

        qbdsDirParty        = qbdsVendTable.addDataSource(tableNum(DirPartyTable));
        qbdsDirParty.relations(false);
        qbdsDirParty.addLink(fieldNum(VendTable, Party), fieldNum(DirPartyTable, RecId));
        qbdsDirParty.addSelectionField(fieldNum(DirPartyTable, Name));
        qbdsDirParty.fields().dynamic(0);

        qbdsVendBankAccount       = qbdsSysDataBaseLog.addDataSource(tableNum(VendBankAccount));
        qbdsVendBankAccount.relations(false);
        qbdsVendBankAccount.addLink(fieldNum(SysDataBaseLog, LogRecId), fieldNum(VendBankAccount, RecId));
        qbdsVendBankAccount.addSelectionField(fieldNum(VendBankAccount, VendAccount));
        qbdsVendBankAccount.fields().dynamic(0);

        qbdsVendTableBank       = qbdsVendBankAccount.addDataSource(tableNum(VendTable));
        qbdsVendTableBank.relations(false);
        qbdsVendTableBank.addLink(fieldNum(VendBankAccount, vendAccount), fieldNum(VendTable, AccountNum));
        qbdsVendTableBank.addSelectionField(fieldNum(VendTable, AccountNum));
        qbdsVendTableBank.fields().dynamic(0);


        // Add required ranges
        // VendorTableID range in SysDatabaseLog
        qbdsSysDataBaseLog.addRange(fieldNum(SysDataBaseLog, Table)).value(int2Str(tableNum(VendTable)));
        qbdsSysDataBaseLog.addRange(fieldNum(SysDataBaseLog, Table)).value(int2Str(tableNum(VendBankAccount)));
        // Date range
        qbdsSysDataBaseLog.addRange(fieldNum(SysDataBaseLog, CreatedDateTime)).value(queryRange(contract.parmFromDateChange(), contract.parmToDateChange()));
        //Legal entity range
        legalEntityList     = contract.parmLegalEntity();
        legalEntityListEnum = legalEntityList.getEnumerator();
        while (legalEntityListEnum.moveNext())
        {
            query.allowCrossCompany(true);
            query.addCompanyRange(legalEntityListEnum.current());
        }

        // Vendor account range
        if (!contract.parmVendAccount().empty())
        {
            vendAccountList     = contract.parmVendAccount();
            vendAccountListEnum = vendAccountList.getEnumerator();
            while (vendAccountListEnum.moveNext())
            {
                qbdsVendTable.addRange(fieldNum(Vendtable, accountNum)).value(vendAccountListEnum.current());
                qbdsVendBankAccount.addRange(fieldNum(VendBankAccount, VendAccount)).value(vendAccountListEnum.current());
            }
        }

        // Vendor group range
        vendGroupList     = contract.parmVendGroup();
        vendGrouplistEnum = vendGroupList.getEnumerator();
        while (vendGrouplistEnum.moveNext())
        {
            qbdsVendTable.addRange(fieldNum(Vendtable, vendGroup)).value(vendGrouplistEnum.current());
            qbdsVendTableBank.addRange(fieldNum(Vendtable, vendGroup)).value(vendGrouplistEnum.current());
        }

        return query;
    }

    /// <summary>
    /// MPJ_3863 - kscerri - 06/08/2021
    /// processes data
    /// </summary>
    /// <param name = "_query">query</param>
    public void processData(Query _query)
    {
        QueryRun            queryRun;
        VendTable           vendTable;
        SysDataBaseLog      sysDataBaseLog;
        DirPartyTable       dirPartyTable;
        List                list = new List(Types::Container);
        ListEnumerator      listEnumerator;
        container           change;
        System.String       fieldString;
        System.Object       newValue;
        System.Object       oldValue;

        CustVendorBlocked   blocked;
        VendBankAccount     vendBankAccount;
       
        if (_query)
        {
            queryRun = new QueryRun(_query);
            
            if(!queryRun.next())
            {
                throw warning ("@MET:VendAuditReportWarning");
            }

            do
            {
                vendTable       = queryRun.get(tableNum(VendTable));
                sysDataBaseLog  = queryRun.get(tableNum(SysDataBaseLog));
                dirPartyTable   = queryRun.get(tableNum(DirPartyTable));
                vendBankAccount = queryRun.get(tableNum(VendBankAccount));
                
                list            = sysDataBaseLog.getDataAslist();
                listEnumerator  =  list.getEnumerator();
                while (listEnumerator.moveNext())
                {
                    change = listEnumerator.current();
                    [fieldString, newValue, oldValue] = change;

                    if (fieldId2Name(sysDataBaseLog.table, str2int(fieldString)) != fieldStr(VendTable, ModifiedDateTime) &&
                        fieldId2Name(sysDataBaseLog.table, str2int(fieldString)) != fieldStr(VendTable, ModifiedBy))
                    {
                        ttsbegin;
                        vendAuditReportTmp.DateOfChange         = sysDataBaseLog.CreatedDateTime;
                        if(vendTable)
                        {
                            vendAuditReportTmp.AccountNum           = vendTable.AccountNum;
                            vendAuditReportTmp.VendName             = dirPartyTable.Name;
                        }
                        else
                        {
                            vendAuditReportTmp.AccountNum           = vendBankAccount.VendAccount;
                            vendAuditReportTmp.VendName             = dirPartyTable::findRec(vendTable::find(vendBankAccount.VendAccount).party).Name;
                        }
                        vendAuditReportTmp.LegalEntity          = sysDataBaseLog.DataAreaId;
                        vendAuditReportTmp.NewChange            = METNewChange::Change;
                        vendAuditReportTmp.UserIdCreatedBy      = sysDataBaseLog.CreatedBy;
                        vendAuditReportTmp.Field                = fieldId2Name(sysDataBaseLog.table, str2int(fieldString));
                        vendAuditReportTmp.SourceTable          = tableId2Name(sysDataBaseLog.table);

                        if (fieldId2Name(sysDataBaseLog.table, str2int(fieldString)) == fieldStr(VendTable, Blocked))
                        {
                            blocked = newValue;
                            vendAuditReportTmp.NewValue             = enum2Str(blocked);
                            blocked = oldValue;
                            vendAuditReportTmp.OldValue             = enum2Str(blocked);
                        }
                        else
                        {
                            vendAuditReportTmp.NewValue             = newValue;
                            vendAuditReportTmp.OldValue             = oldValue;
                        }
                        vendAuditReportTmp.insert();
                        ttscommit;
                    }
                }                                
            } while (queryRun.next());

        }
    }
